/*
 * This file was generated by the Gradle 'init' task.
 *
 * This generated file contains a sample Java application project to get you started.
 * For more details on building Java & JVM projects, please refer to https://docs.gradle.org/8.14.4/userguide/building_java_projects.html in the Gradle documentation.
 */

plugins {
    java
    // Apply the application plugin to add support for building a CLI application in Java.
    application
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    // Use JUnit test framework.
    testImplementation(libs.junit)

    // This dependency is used by the application.
    implementation(libs.guava)
    // 1. Сам Javalin (укажите актуальную версию, например, 6.x)
    implementation("io.javalin:javalin:6.3.0")

    // 2. Логгер (обязателен, иначе Javalin выдаст предупреждение и не запустится)
    implementation("org.slf4j:slf4j-simple:2.0.13")

    // 3. Jackson (нужен для метода ctx.json(), чтобы автоматически сериализовать объекты в JSON)
    implementation("com.fasterxml.jackson.core:jackson-databind:2.17.1")
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

application {
    // Define the main class for the application.
    mainClass = "org.example.App"
}
